"""Annotate lines of code with line numbers and coverage status."""
def annotate_code(path: Any, code: Any, coverage: Any) -> object {
    return [
        {
            'num': (line_num + 1),
            'status': str(coverage.lookup(path, (line_num + 1))).lower(),
            'code': line
        } for (line_num, line) in enumerate(code.splitlines())
    ];
}

"""Read in service_time values from requests."""
def _get_process_times(process_times: Any, requests: Any) -> object {
    for req in requests {
        if ('service_time' in req) {
            process_times[int(req['@node'])] = float(req['service_time']);
        }
    }
    return process_times;
}

